insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-panel-light-2x4-40w', 'GSW-LEDPANELLI', 'LED Panel Light 2x4 – 40W', 'commercial-lighting', 'led-flat-panel', 850, null, true, 'Premium 2x4 edge-lit flat panel with 0-10V dimming driver, DLC Premium listed.', 'Premium 2x4 edge-lit flat panel with 0-10V dimming driver, DLC Premium listed.', '["40W | 4400 lm","3500K/4000K/5000K","0-10V dimmable, 120-277V","DLC Premium | cULus | 5-yr"]'::jsonb, 'in-stock', 'LED Panel Light 2x4 – 40W Canada', 'Buy the LED Panel Light 2x4 – 40W wholesale in Canada. 40W | 4400 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Panel Light 2x4 – 40W is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. 40W | 4400 lm with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, '/images/products/test.jpg');
