insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('traditional-led-wallpack-100w-120w', 'GSW-TRADITIONA', '100W/120W Traditional LED Wallpack', 'commercial-lighting', 'led-wall-pack', 450, 500, true, 'Traditional-style full cutoff wallpack with selectable 100W/120W output and built-in photocell.', 'Traditional-style full cutoff wallpack with selectable 100W/120W output and built-in photocell.', '["Selectable 100W/120W | 14,400–17,200 lm","5000K, Type III optics","120-277V, photocell included","cULus | DLC Premium | 5-yr"]'::jsonb, 'low-stock', '100W/120W Traditional LED Wallpack', 'Buy the 100W/120W Traditional LED Wallpack wholesale in Canada. Selectable 100W/120W | 14,400–17,200 lm — cULus/DLC certified, flat $30 shipping.', 'The 100W/120W Traditional LED Wallpack is a full-cutoff LED wall pack for building perimeters, loading docks and egress routes. Selectable 100W/120W | 14,400–17,200 lm with a photocell option so the light manages itself from dusk to dawn. Commercial contractors across Toronto and the GTA buy LED wall packs wholesale from GSW for the mix of DLC-listed product, real stock and counter pickup in Mississauga.', '[{"q":"Does the wall pack include a photocell?","a":"Most of our wall packs accept a twist-lock photocell and several ship with one included — check the spec table on this model. We always confirm the configuration when you order by phone."},{"q":"Full cutoff — what does that mean?","a":"A full-cutoff optic directs all light downward, eliminating uplight and meeting dark-sky and light-trespass requirements common in GTA municipalities."}]'::jsonb, '/images/products/100w-120w-traditional-led-wallpack.jpg');
