insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('asymmetric-flood-lights', 'GSW-ASYMMETRIC', 'Asymmetric Flood Lights', 'commercial-lighting', 'led-flood-light', 1000, null, true, 'Stadium-grade asymmetric floodlight with precise beam control for arenas, facades and yards.', 'Stadium-grade asymmetric floodlight with precise beam control for arenas, facades and yards.', '["High-output modular LED engine","Asymmetric / street-beam optics","120-480V, 1-10V + DALI options","IP66 | cULus | 5-year warranty"]'::jsonb, 'in-stock', 'Asymmetric Flood Lights Canada', 'Buy the Asymmetric Flood Lights wholesale in Canada. High-output modular LED engine — cULus/DLC certified, flat $30 shipping.', 'The Asymmetric Flood Lights is a high-output LED flood light engineered for large areas — parking lots, yards, facades and sports surfaces. High-output modular LED engine with precision optics that put light on the target, not the neighbours. GSW is a Canadian wholesale LED lighting supplier, so flood lights ship flat-rate across the country and are always available for pickup at our Mississauga counter.', '[{"q":"How do I choose wattage for a parking lot?","a":"As a rule of thumb, 100W–150W LED replaces a 400W metal halide shoebox or flood. Tell us the pole height and spacing and we will run a quick layout to confirm foot-candles before you commit."},{"q":"Are these lights dimmable or motion-controllable?","a":"Most models accept 0-10V dimming and pair with motion sensors or photocells for after-hours energy savings. We stock compatible controls."}]'::jsonb, '/images/products/asymmetric-flood-lights.jpg');
