insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-commercial-downlight-30w', 'GSW-LEDCOMMERC', 'LED Commercial Downlight 30W', 'commercial-lighting', 'led-recessed-down-light', 74, 92, false, '8-inch commercial recessed downlight with high CRI for lobbies, retail and healthcare.', '8-inch commercial recessed downlight with high CRI for lobbies, retail and healthcare.', '["30W | 3300 lm","3500K/4000K, 90+ CRI","0-10V dimmable, 120-347V","cULus | IC-rated | 5-yr"]'::jsonb, 'in-stock', 'LED Commercial Downlight 30W Canada', 'Buy the LED Commercial Downlight 30W wholesale in Canada. 30W | 3300 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Commercial Downlight 30W is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. 30W | 3300 lm, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/extras/4-inch-mounting-plate.jpg');
