insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-slim-canopy-70w', 'GSW-LEDSLIMCAN', 'LED Slim Canopy Light 70W', 'commercial-lighting', 'led-slim-canopy-light', 96, 120, false, 'Low-profile surface-mount canopy for gas stations, drive-throughs and parkades.', 'Low-profile surface-mount canopy for gas stations, drive-throughs and parkades.', '["70W | 9100 lm","5000K, wide distribution","120-277V, 0-10V dimmable","DLC listed | cULus | IP65"]'::jsonb, 'in-stock', 'LED Slim Canopy Light 70W Canada', 'Buy the LED Slim Canopy Light 70W wholesale in Canada. 70W | 9100 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Slim Canopy Light 70W is a slim surface-mount LED canopy light for gas stations, drive-throughs, parkades and covered walkways. 70W | 9100 lm in a low-profile housing that mounts where bulkier HID fixtures cannot. Gas station and retail contractors across the GTA buy canopy lighting wholesale from GSW with stock on the shelf and flat $30 Canada-wide shipping.', '[{"q":"Will this fit my existing canopy cut-out?","a":"Slim canopy lights are designed to surface-mount or cover legacy HID openings. Send us a photo of the existing opening and dimensions and we will confirm fit before you order."},{"q":"Is the fixture rated for fuel-canopy use?","a":"These fixtures are UL/cUL listed for wet locations. Class I Division 2 hazardous-location ratings are a separate listing — tell us about the site classification and we will supply the correct model."}]'::jsonb, null);
