insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-shoebox-150w', 'GSW-LEDSHOEBOX', 'LED Shoebox Light 150W', 'commercial-lighting', 'led-outdoor-shoebox-light', 128, 160, false, 'Parking lot shoebox with slip-fitter mount, photocell and Type III/IV/V optics.', 'Parking lot shoebox with slip-fitter mount, photocell and Type III/IV/V optics.', '["150W | 19,500 lm","5000K, field-selectable optics","120-277V, photocell included","DLC Premium | cULus | IP66"]'::jsonb, 'in-stock', 'LED Shoebox Light 150W Canada', 'Buy the LED Shoebox Light 150W wholesale in Canada. 150W | 19,500 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Shoebox Light 150W is an LED shoebox area light for parking lots, roadways and big-box retail sites. 150W | 19,500 lm with field-selectable optics and an included photocell for dusk-to-dawn operation. Canadian contractors buy shoebox lighting wholesale from GSW — DLC-listed product, 10kV surge protection options, and flat-rate shipping to any job site in the country.', '[{"q":"Pole mount or wall mount?","a":"Shoeboxes typically mount on poles with a slip-fitter (2-3/8 inch tenon) — we stock adapters for wall and trunnion mounting too. Tell us the pole schedule and we will configure the order."},{"q":"What optic do I need?","a":"Type III throws light forward along roadways and aisles; Type IV is symmetrical for open lots; Type V is a broad square for centred poles. We can help choose from the site plan or photometric."}]'::jsonb, '/images/extras/led-parking-lot-lights-led-shoe-box-lamp.jpg');
