insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-post-top-60w', 'GSW-LEDPOSTTOP', 'LED Post Top Light 60W', 'commercial-lighting', 'led-post-top-light', 92, 115, false, 'Decorative acorn post-top for parking lots, pathways and municipal streetscapes.', 'Decorative acorn post-top for parking lots, pathways and municipal streetscapes.', '["60W | 7800 lm","3000K/4000K/5000K","120-277V, photocell optional","DLC listed | cULus | IP65"]'::jsonb, 'in-stock', 'LED Post Top Light 60W Canada', 'Buy the LED Post Top Light 60W wholesale in Canada. 60W | 7800 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Post Top Light 60W is a decorative LED post top light for pathways, parks, parking areas and streetscapes. 60W | 7800 lm in a housing that upgrades the look of the site while cutting energy versus HID by more than half. Municipal, condo and commercial buyers across Canada source post tops from GSW at wholesale pricing with dependable stock.', '[{"q":"What pole does it mount to?","a":"Most post tops fit a standard 3-inch OD tenon. Adapters are available for larger poles; call with your pole detail and we will match the mounting."},{"q":"Is a photocell included?","a":"Many models ship photocell-ready with the cell available as an option. We typically supply units with photocells for dusk-to-dawn sites — just ask when ordering."}]'::jsonb, '/images/products/led-flood-parking-lot-street-light.jpg');
