insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-strip-fixture-4ft-40w', 'GSW-LEDSTRIPFI', 'LED Linear Strip Fixture 4ft – 40W', 'commercial-lighting', 'led-linear-strip-fixture', 46, 58, false, '4-foot LED striplight for utility areas, retail back rooms and continuous rows.', '4-foot LED striplight for utility areas, retail back rooms and continuous rows.', '["40W | 5200 lm","4000K/5000K","120-277V, 0-10V dimmable","DLC listed | cULus"]'::jsonb, 'in-stock', 'LED Linear Strip Fixture 4ft – 40W', 'Buy the LED Linear Strip Fixture 4ft – 40W wholesale in Canada. 40W | 5200 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Linear Strip Fixture 4ft – 40W is a commercial LED striplight for utility areas, retail back rooms and continuous-row installations. 40W | 5200 lm in a slim housing that links end-to-end for clean, continuous runs. GTA contractors buy striplights wholesale from GSW because we stock 4ft and 8ft lengths in quantity and deliver to the job site on schedule.', '[{"q":"Can I link multiple fixtures in a row?","a":"Yes — striplights link end-to-end with connector whips, and rows can be fed from a single junction. We can plan the feed points with you if you share the room dimensions."},{"q":"4ft or 8ft — which is more economical?","a":"8ft fixtures use fewer housings and junction boxes per foot of run, which usually wins on installed cost for long rows. 4ft units are easier to handle and fit in chopped-up spaces."}]'::jsonb, '/images/extras/wkiaivjqmycfsa2taaemtkibiwe630.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-strip-fixture-8ft-80w', 'GSW-LEDSTRIPFI', 'LED Linear Strip Fixture 8ft – 80W', 'commercial-lighting', 'led-linear-strip-fixture', 82, 99, false, '8-foot wraparound striplight with prismatic lens for warehouses and workshops.', '8-foot wraparound striplight with prismatic lens for warehouses and workshops.', '["80W | 10,400 lm","5000K daylight","120-277V, linkable rows","cULus certified | 5-yr warranty"]'::jsonb, 'in-stock', 'LED Linear Strip Fixture 8ft – 80W', 'Buy the LED Linear Strip Fixture 8ft – 80W wholesale in Canada. 80W | 10,400 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Linear Strip Fixture 8ft – 80W is a commercial LED striplight for utility areas, retail back rooms and continuous-row installations. 80W | 10,400 lm in a slim housing that links end-to-end for clean, continuous runs. GTA contractors buy striplights wholesale from GSW because we stock 4ft and 8ft lengths in quantity and deliver to the job site on schedule.', '[{"q":"Can I link multiple fixtures in a row?","a":"Yes — striplights link end-to-end with connector whips, and rows can be fed from a single junction. We can plan the feed points with you if you share the room dimensions."},{"q":"4ft or 8ft — which is more economical?","a":"8ft fixtures use fewer housings and junction boxes per foot of run, which usually wins on installed cost for long rows. 4ft units are easier to handle and fit in chopped-up spaces."}]'::jsonb, '/images/extras/wkiaivjqw9atsnquaahw9r9fqti541.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-vapor-tight-4ft-40w', 'GSW-LEDVAPORTI', 'LED Vapor Tight Fixture 4ft – 40W', 'commercial-lighting', 'led-vapor-tight-fixture', 68, 85, false, 'IP65 sealed 4ft fixture with gasketed lens for garages, car washes and cold storage.', 'IP65 sealed 4ft fixture with gasketed lens for garages, car washes and cold storage.', '["40W | 5200 lm","4000K/5000K","120-277V, wet-location listed","IP65 | cULus | corrosion resistant"]'::jsonb, 'in-stock', 'LED Vapor Tight Fixture 4ft – 40W', 'Buy the LED Vapor Tight Fixture 4ft – 40W wholesale in Canada. 40W | 5200 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Vapor Tight Fixture 4ft – 40W is a sealed, gasketed LED vapor tight fixture for parking garages, car washes, tunnels and cold storage. 40W | 5200 lm behind an impact-resistant lens that keeps out moisture, dust and corrosion. Contractors building parkades and wash bays across Canada buy vapor tight lighting from GSW for the IP65/IP66 rating depth and fast flat-rate shipping.', '[{"q":"IP65 vs IP66 — what is the difference?","a":"Both are dust-tight and hose-proof; IP66 adds protection against powerful jets, which matters in wash-down and pressure-wash environments. We stock both — tell us the cleaning regime and we will spec it."},{"q":"Does it handle cold temperatures?","a":"Yes — LED vapor tights with quality drivers start reliably well below freezing, making them the standard for unheated parkades and cold storage across Canada."}]'::jsonb, null);
