insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-track-head-20w', 'GSW-LEDTRACKHE', 'LED Track Head 20W', 'commercial-lighting', 'led-track-light', 32, 40, false, 'Compact H-type track head with 90+ CRI for retail merchandising and galleries.', 'Compact H-type track head with 90+ CRI for retail merchandising and galleries.', '["20W | 2000 lm","2700K–5000K selectable","120V, H/J/L adapters available","cULus certified | 5-yr warranty"]'::jsonb, 'in-stock', 'LED Track Head 20W Canada', 'Buy the LED Track Head 20W wholesale in Canada. 20W | 2000 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Track Head 20W is a precision LED track light for retail displays, galleries and hospitality spaces. 20W | 2000 lm with the aiming flexibility merchandisers need and the colour quality that makes product pop. Retail fit-out contractors across Toronto buy track lighting wholesale from GSW, with H/J/L adapter compatibility confirmed before you order.', '[{"q":"Which track system does it fit?","a":"Our track heads are available with H-type, J-type and L-type adapters to match existing track. New installs typically use H-type — we stock track, connectors and heads as a complete system."},{"q":"What beam angle should I choose?","a":"Narrow 15–24° spots highlight individual products; 36–40° accents cover wall sections; floods wash general areas. Mixed angles on one run give the layered look designers want."}]'::jsonb, null);
