insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('device-box-2x4-deep', 'GSW-DEVICEBOX2', '2"x4" Steel Device Box – Deep', 'electrical-materials', 'device-box', 3.2, null, false, 'Deep 2x4 galvanized device box with knockouts for device and fixture mounting.', 'Deep 2x4 galvanized device box with knockouts for device and fixture mounting.', '["2-1/8\" deep, 1/2\" & 3/4\" KOs","Galvanized steel","cULus listed, CSA certified","Qty pricing per 25-pack"]'::jsonb, 'in-stock', '2"x4" Steel Device Box – Deep', 'Buy the 2"x4" Steel Device Box – Deep wholesale in Canada. 2-1/8" deep, 1/2" & 3/4" KOs — cULus/DLC certified, flat $30 shipping.', 'The 2"x4" Steel Device Box – Deep is a cULus-listed steel device box for device, fixture and junction mounting in residential and commercial rough-ins. 2-1/8" deep, 1/2" & 3/4" KOs, formed from galvanized steel with clean knockouts that punch without tearing. GSW is an electrical materials supplier in Mississauga with device boxes on the shelf by the case — priced for contractors, not retail.', '[{"q":"What is the difference between a device box and a handy box?","a":"Device boxes are gangable 2x4 or 4x4 boxes for flush device mounting; handy boxes are single-gang surface boxes used with raised covers for exposed work. We stock both — tell us the application."},{"q":"Do you sell by the case?","a":"Yes — all our boxes and covers are case-quantity priced, and mixed-case orders are fine. Call the counter for your contractor pricing tier."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('device-box-handy', 'GSW-DEVICEBOXH', 'Handy Box 4"x2-1/8" – Raised Cover', 'electrical-materials', 'device-box', 4.1, 5.25, false, 'Handy box with raised device cover for surface-mounted receptacles and switches.', 'Handy box with raised device cover for surface-mounted receptacles and switches.', '["1-7/16\" deep","1/2\" knockouts, drawn construction","cULus listed | CSA approved","Includes raised cover"]'::jsonb, 'in-stock', 'Handy Box 4"x2-1/8" – Raised Cover', 'Buy the Handy Box 4"x2-1/8" – Raised Cover wholesale in Canada. 1-7/16" deep — cULus/DLC certified, flat $30 shipping.', 'The Handy Box 4"x2-1/8" – Raised Cover is a cULus-listed steel device box for device, fixture and junction mounting in residential and commercial rough-ins. 1-7/16" deep, formed from galvanized steel with clean knockouts that punch without tearing. GSW is an electrical materials supplier in Mississauga with device boxes on the shelf by the case — priced for contractors, not retail.', '[{"q":"What is the difference between a device box and a handy box?","a":"Device boxes are gangable 2x4 or 4x4 boxes for flush device mounting; handy boxes are single-gang surface boxes used with raised covers for exposed work. We stock both — tell us the application."},{"q":"Do you sell by the case?","a":"Yes — all our boxes and covers are case-quantity priced, and mixed-case orders are fine. Call the counter for your contractor pricing tier."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('nmd90-14-2-copper', 'GSW-NMD90142CO', 'NMD90 14/2 Copper Building Wire – 150m', 'electrical-materials', 'wire', 92, 108, false, '14/2 NMD90 non-metallic sheathed cable for residential branch circuits.', '14/2 NMD90 non-metallic sheathed cable for residential branch circuits.', '["14 AWG, 2 conductor + bond","300V, rated -25°C to 90°C","CSA certified | FT4 rated","150 m coil"]'::jsonb, 'in-stock', 'NMD90 14/2 Copper Building Wire –…', 'Buy the NMD90 14/2 Copper Building Wire – 150m wholesale in Canada. 14 AWG, 2 conductor + bond — cULus/DLC certified, flat $30 shipping.', 'The NMD90 14/2 Copper Building Wire – 150m is CSA-certified copper building wire for branch circuits, feeders and service runs. 14 AWG, 2 conductor + bond, rated for Canadian temperatures and pulling through cold conduit. Electrical contractors across the GTA buy wire from GSW’s Mississauga warehouse because we keep full reels and coils in stock with honest per-metre and per-reel pricing.', '[{"q":"NMD90 vs RW90 — which do I need?","a":"NMD90 is non-metallic sheathed cable for wood-frame residential work; RW90 is a single conductor for conduit, commercial and industrial runs. Your drawings will call one out — if not, call us and we will confirm the code requirement."},{"q":"Can I return unused wire?","a":"Full, undamaged reels and coils in original packaging can usually be returned or credited — ask about our current return policy when you order so we can note it on the account."}]'::jsonb, '/images/extras/electri.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rw90-12-1-stranded', 'GSW-RW90121STR', 'RW90 12 AWG Stranded – 300m', 'electrical-materials', 'wire', 128, null, false, 'RW90 cross-linked polyethylene single conductor for commercial and industrial runs.', 'RW90 cross-linked polyethylene single conductor for commercial and industrial runs.', '["12 AWG stranded, bare or tinned","600V, 90°C wet/dry","CSA certified | FT4","300 m reel"]'::jsonb, 'in-stock', 'RW90 12 AWG Stranded – 300m Canada', 'Buy the RW90 12 AWG Stranded – 300m wholesale in Canada. 12 AWG stranded, bare or tinned — cULus/DLC certified, flat $30 shipping.', 'The RW90 12 AWG Stranded – 300m is CSA-certified copper building wire for branch circuits, feeders and service runs. 12 AWG stranded, bare or tinned, rated for Canadian temperatures and pulling through cold conduit. Electrical contractors across the GTA buy wire from GSW’s Mississauga warehouse because we keep full reels and coils in stock with honest per-metre and per-reel pricing.', '[{"q":"NMD90 vs RW90 — which do I need?","a":"NMD90 is non-metallic sheathed cable for wood-frame residential work; RW90 is a single conductor for conduit, commercial and industrial runs. Your drawings will call one out — if not, call us and we will confirm the code requirement."},{"q":"Can I return unused wire?","a":"Full, undamaged reels and coils in original packaging can usually be returned or credited — ask about our current return policy when you order so we can note it on the account."}]'::jsonb, '/images/extras/electri.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('receptacle-15a-decorator', 'GSW-RECEPTACLE', 'Decorator Receptacle 15A – Commercial Grade', 'electrical-materials', 'device', 5.6, 7.25, false, 'Commercial-grade 15A 125V tamper-resistant decorator receptacle with screw terminals.', 'Commercial-grade 15A 125V tamper-resistant decorator receptacle with screw terminals.', '["15A / 125V, TR compliant","Back & side wired","cULus listed, CSA certified","10-year warranty, white/ivory"]'::jsonb, 'in-stock', 'Decorator Receptacle 15A – Commerc…', 'Buy the Decorator Receptacle 15A – Commercial Grade wholesale in Canada. 15A / 125V, TR compliant — cULus/DLC certified, flat $30 shipping.', 'The Decorator Receptacle 15A – Commercial Grade is a commercial-grade electrical device rated for the demands of everyday contractor use — not the big-box residential line. 15A / 125V, TR compliant with back and side wiring for fast installs. GSW stocks receptacles, switches, GFCI and dimmers at the Mississauga counter in contractor case quantities.', '[{"q":"Commercial grade vs residential grade — does it matter?","a":"Yes. Commercial-grade devices use thicker contacts and bodies rated for heavier use — they survive ten-tenant condos and retail traffic where residential devices fail early. The price difference is small; the callbacks are not."},{"q":"Do you stock tamper-resistant and GFCI devices?","a":"Yes — TR receptacles are code-required in most residential locations, and we stock GFCI in 15A and 20A, plus AFCI breakers to match. Everything to pass inspection in one order."}]'::jsonb, '/images/hero/office-2.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('switch-15a-3way', 'GSW-SWITCH15A3', '3-Way Switch 15A – Commercial Grade', 'electrical-materials', 'device', 4.8, null, false, 'Commercial-spec 15A 3-way toggle switch rated for 100,000 operations.', 'Commercial-spec 15A 3-way toggle switch rated for 100,000 operations.', '["15A / 120-277V AC","Back & side wired","cULus listed | CSA approved","White, brown, grey available"]'::jsonb, 'in-stock', '3-Way Switch 15A – Commercial Grade', 'Buy the 3-Way Switch 15A – Commercial Grade wholesale in Canada. 15A / 120-277V AC — cULus/DLC certified, flat $30 shipping.', 'The 3-Way Switch 15A – Commercial Grade is a commercial-grade electrical device rated for the demands of everyday contractor use — not the big-box residential line. 15A / 120-277V AC with back and side wiring for fast installs. GSW stocks receptacles, switches, GFCI and dimmers at the Mississauga counter in contractor case quantities.', '[{"q":"Commercial grade vs residential grade — does it matter?","a":"Yes. Commercial-grade devices use thicker contacts and bodies rated for heavier use — they survive ten-tenant condos and retail traffic where residential devices fail early. The price difference is small; the callbacks are not."},{"q":"Do you stock tamper-resistant and GFCI devices?","a":"Yes — TR receptacles are code-required in most residential locations, and we stock GFCI in 15A and 20A, plus AFCI breakers to match. Everything to pass inspection in one order."}]'::jsonb, '/images/extras/electri.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('loadcentre-100a-20-space', 'GSW-LOADCENTRE', 'Loadcentre 100A – 20/40 Space', 'electrical-materials', 'panel-board-breakers', 96, 118, false, 'Main-breaker loadcentre with 20 spaces / 40 circuits, 100A, indoor enclosure.', 'Main-breaker loadcentre with 20 spaces / 40 circuits, 100A, indoor enclosure.', '["100A main breaker","20 spaces / 40 circuits, 1-ph 3-wire","CSA certified | ESA accepted","Indoor NEMA 1 enclosure"]'::jsonb, 'in-stock', 'Loadcentre 100A – 20/40 Space', 'Buy the Loadcentre 100A – 20/40 Space wholesale in Canada. 100A main breaker — cULus/DLC certified, flat $30 shipping.', 'The Loadcentre 100A – 20/40 Space is a CSA-certified loadcentre or breaker for service and distribution work. 100A main breaker, accepted by ESA inspectors across Ontario. Contractors doing service upgrades and commercial distribution buy panels and breakers from GSW for the in-stock selection and the confidence that what we sell passes inspection the first time.', '[{"q":"Do you sell panels with the breakers bundled?","a":"Yes — we can supply loadcentres pre-loaded with the breaker schedule, which saves the job-site sorting time. Send the panel schedule and we will quote it assembled."},{"q":"Can I mix breaker brands in my panel?","a":"Generally no — panels accept only their manufacturer’s listed breakers (or approved classified types). Tell us the panel make and we will match breakers that are listed for it."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('breaker-2pole-40a', 'GSW-BREAKER2PO', '2-Pole Breaker 40A – Bolt-on', 'electrical-materials', 'panel-board-breakers', 28, 35, false, '2-pole 40A thermal-magnetic bolt-on breaker for commercial panelboards.', '2-pole 40A thermal-magnetic bolt-on breaker for commercial panelboards.', '["40A, 2-pole, 120/240V","10 kAIC interrupt rating","cULus listed | CSA certified","Fits major panelboard types"]'::jsonb, 'in-stock', '2-Pole Breaker 40A – Bolt-on Canada', 'Buy the 2-Pole Breaker 40A – Bolt-on wholesale in Canada. 40A, 2-pole, 120/240V — cULus/DLC certified, flat $30 shipping.', 'The 2-Pole Breaker 40A – Bolt-on is a CSA-certified loadcentre or breaker for service and distribution work. 40A, 2-pole, 120/240V, accepted by ESA inspectors across Ontario. Contractors doing service upgrades and commercial distribution buy panels and breakers from GSW for the in-stock selection and the confidence that what we sell passes inspection the first time.', '[{"q":"Do you sell panels with the breakers bundled?","a":"Yes — we can supply loadcentres pre-loaded with the breaker schedule, which saves the job-site sorting time. Send the panel schedule and we will quote it assembled."},{"q":"Can I mix breaker brands in my panel?","a":"Generally no — panels accept only their manufacturer’s listed breakers (or approved classified types). Tell us the panel make and we will match breakers that are listed for it."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('safety-switch-60a-nonfusible', 'GSW-SAFETYSWIT', 'Safety Switch 60A – Non-Fusible', 'electrical-materials', 'disconnect-switch-fuses', 74, 92, false, 'Heavy-duty non-fusible safety switch in NEMA 3R enclosure for outdoor service.', 'Heavy-duty non-fusible safety switch in NEMA 3R enclosure for outdoor service.', '["60A, 600V max, 3-pole","NEMA 3R rain-tight enclosure","cULus listed | CSA certified","Quick-make/quick-break mechanism"]'::jsonb, 'in-stock', 'Safety Switch 60A – Non-Fusible', 'Buy the Safety Switch 60A – Non-Fusible wholesale in Canada. 60A, 600V max, 3-pole — cULus/DLC certified, flat $30 shipping.', 'The Safety Switch 60A – Non-Fusible is a heavy-duty safety switch or fuse for isolating equipment per code. 60A, 600V max, 3-pole with quick-make/quick-break mechanisms and rain-tight enclosures where the job demands them. HVAC, machine and service contractors across the GTA source disconnects and fuses from GSW with same-day counter availability.', '[{"q":"Fusible or non-fusible — which do I need?","a":"Non-fusible switches are local isolators only; fusible switches add overcurrent protection via Class J or R fuses. The equipment nameplate and code determine which — send us the spec and we will match it."},{"q":"Which fuse class fits my switch?","a":"Most modern disconnects take Class J; older equipment may use Class R or H. The switch label lists acceptable classes — bring the part number or a photo and we will identify the right fuse."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('fuse-class-j-30a', 'GSW-FUSECLASSJ', 'Class J Fuse 30A – Time Delay', 'electrical-materials', 'disconnect-switch-fuses', 14.5, null, false, 'Time-delay Class J dual-element fuse for motor and transformer protection.', 'Time-delay Class J dual-element fuse for motor and transformer protection.', '["30A, 600V AC, Class J","Time-delay, 200kA IR","cULus listed | CSA certified","10-pack contractor pricing"]'::jsonb, 'in-stock', 'Class J Fuse 30A – Time Delay', 'Buy the Class J Fuse 30A – Time Delay wholesale in Canada. 30A, 600V AC, Class J — cULus/DLC certified, flat $30 shipping.', 'The Class J Fuse 30A – Time Delay is a heavy-duty safety switch or fuse for isolating equipment per code. 30A, 600V AC, Class J with quick-make/quick-break mechanisms and rain-tight enclosures where the job demands them. HVAC, machine and service contractors across the GTA source disconnects and fuses from GSW with same-day counter availability.', '[{"q":"Fusible or non-fusible — which do I need?","a":"Non-fusible switches are local isolators only; fusible switches add overcurrent protection via Class J or R fuses. The equipment nameplate and code determine which — send us the spec and we will match it."},{"q":"Which fuse class fits my switch?","a":"Most modern disconnects take Class J; older equipment may use Class R or H. The switch label lists acceptable classes — bring the part number or a photo and we will identify the right fuse."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('transformer-45kva-600-208', 'GSW-TRANSFORME', 'Dry-Type Transformer 45 kVA – 600V to 208Y/120V', 'electrical-materials', 'transformer', 1450, 1690, false, 'Three-phase dry-type distribution transformer, 45 kVA, 600V delta primary.', 'Three-phase dry-type distribution transformer, 45 kVA, 600V delta primary.', '["45 kVA, 3-phase","600V Δ primary / 208Y/120V secondary","CSA certified | DOE 2016 efficient","Aluminum windings, 150°C rise"]'::jsonb, 'made-to-order', 'Dry-Type Transformer 45 kVA – 600V…', 'Buy the Dry-Type Transformer 45 kVA – 600V to 208Y/120V wholesale in Canada. 45 kVA, 3-phase — cULus/DLC certified, flat $30 shipping.', 'The Dry-Type Transformer 45 kVA – 600V to 208Y/120V is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. 45 kVA, 3-phase with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('control-transformer-500va', 'GSW-CONTROLTRA', 'Control Transformer 500VA – 240/480 to 120V', 'electrical-materials', 'transformer', 86, null, false, 'Industrial control transformer for machine panels and motor-control circuits.', 'Industrial control transformer for machine panels and motor-control circuits.', '["500 VA, 1-phase","240x480V primary / 120V secondary","cULus listed | CSA certified","Foot or DIN-rail mountable"]'::jsonb, 'in-stock', 'Control Transformer 500VA – 240/48…', 'Buy the Control Transformer 500VA – 240/480 to 120V wholesale in Canada. 500 VA, 1-phase — cULus/DLC certified, flat $30 shipping.', 'The Control Transformer 500VA – 240/480 to 120V is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. 500 VA, 1-phase with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('meter-socket-200a-overhead', 'GSW-METERSOCKE', 'Meter Socket 200A – Overhead', 'electrical-materials', 'service-meter-sockets', 68, 84, false, '200A overhead single-position meter socket with ringless cover, Ontario spec.', '200A overhead single-position meter socket with ringless cover, Ontario spec.', '["200A, 1-phase, 3-wire","Overhead feed, ringless type","CSA certified | ESA accepted","U-guard and hub included"]'::jsonb, 'in-stock', 'Meter Socket 200A – Overhead Canada', 'Buy the Meter Socket 200A – Overhead wholesale in Canada. 200A, 1-phase, 3-wire — cULus/DLC certified, flat $30 shipping.', 'The Meter Socket 200A – Overhead is a CSA-certified meter base for overhead or underground service entrances, built to Ontario utility standards. 200A, 1-phase, 3-wire with ringless covers, lever bypass options and rain-tight NEMA 3R enclosures. GTA electrical contractors buy meter sockets from GSW because our units match what Toronto Hydro, Alectra and Enova inspectors expect to see.', '[{"q":"Overhead or underground — how do I know which socket?","a":"It depends on the service feed to the building: overhead fed from a mast uses an OH socket; underground fed from a conduit uses a UG socket. Your utility connection agreement specifies it — or call us with the service type."},{"q":"What is a lever bypass and do I need one?","a":"A lever bypass lets the utility de-energize the load side without pulling the meter. Many utilities now require it on new services — we stock lever-bypass models so you pass inspection the first time."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('meter-socket-100a-underground', 'GSW-METERSOCKE', 'Meter Socket 100A – Underground', 'electrical-materials', 'service-meter-sockets', 58, null, false, '100A underground meter base with lever bypass for residential service entrances.', '100A underground meter base with lever bypass for residential service entrances.', '["100A, lever bypass","Underground feed, single position","CSA certified | ESA accepted","NEMA 3R enclosure"]'::jsonb, 'in-stock', 'Meter Socket 100A – Underground', 'Buy the Meter Socket 100A – Underground wholesale in Canada. 100A, lever bypass — cULus/DLC certified, flat $30 shipping.', 'The Meter Socket 100A – Underground is a CSA-certified meter base for overhead or underground service entrances, built to Ontario utility standards. 100A, lever bypass with ringless covers, lever bypass options and rain-tight NEMA 3R enclosures. GTA electrical contractors buy meter sockets from GSW because our units match what Toronto Hydro, Alectra and Enova inspectors expect to see.', '[{"q":"Overhead or underground — how do I know which socket?","a":"It depends on the service feed to the building: overhead fed from a mast uses an OH socket; underground fed from a conduit uses a UG socket. Your utility connection agreement specifies it — or call us with the service type."},{"q":"What is a lever bypass and do I need one?","a":"A lever bypass lets the utility de-energize the load side without pulling the meter. Many utilities now require it on new services — we stock lever-bypass models so you pass inspection the first time."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('pvc-conduit-sch40-2in-10ft', 'GSW-PVCCONDUIT', 'PVC Conduit Schedule 40 – 2" x 10ft', 'electrical-materials', 'pvc-conduit-fittings', 12.8, 15.5, false, 'Schedule 40 PVC conduit for underground and concrete-encased runs.', 'Schedule 40 PVC conduit for underground and concrete-encased runs.', '["2\" trade size, 10 ft length","Schedule 40, grey PVC","CSA certified | cULus re-listed","Sunlight resistant"]'::jsonb, 'in-stock', 'PVC Conduit Schedule 40 – 2" x 10ft', 'Buy the PVC Conduit Schedule 40 – 2" x 10ft wholesale in Canada. 2" trade size, 10 ft length — cULus/DLC certified, flat $30 shipping.', 'The PVC Conduit Schedule 40 – 2" x 10ft is CSA-certified PVC raceway for underground, concrete-encased and corrosive-environment runs. 2" trade size, 10 ft length — sunlight-resistant conduit and Schedule 40/80 fittings with the bell ends and threading that make underground work go faster. Civil and electrical contractors across Mississauga buy PVC conduit from GSW by the bundle at wholesale pricing.', '[{"q":"Schedule 40 or Schedule 80 — which do I need?","a":"Schedule 40 is standard for underground and encased work; Schedule 80 is for exposed locations where physical protection is required, and for stub-ups. Drawings typically call it out — we stock both."},{"q":"Do you stock the fittings to match?","a":"Yes — couplings, elbows (including factory 90s), adapters, expansion fittings and solvent cement are all on the shelf, so the underground package comes from one order."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('pvc-coupling-2in-sch80', 'GSW-PVCCOUPLIN', 'PVC Coupling 2" – Schedule 80', 'electrical-materials', 'pvc-conduit-fittings', 2.4, null, false, 'Schedule 80 PVC threaded coupling for rigid underground installations.', 'Schedule 80 PVC threaded coupling for rigid underground installations.', '["2\" trade size","Schedule 80, threaded","cULus listed | CSA certified","Qty pricing per 50-pack"]'::jsonb, 'in-stock', 'PVC Coupling 2" – Schedule 80', 'Buy the PVC Coupling 2" – Schedule 80 wholesale in Canada. 2" trade size — cULus/DLC certified, flat $30 shipping.', 'The PVC Coupling 2" – Schedule 80 is CSA-certified PVC raceway for underground, concrete-encased and corrosive-environment runs. 2" trade size — sunlight-resistant conduit and Schedule 40/80 fittings with the bell ends and threading that make underground work go faster. Civil and electrical contractors across Mississauga buy PVC conduit from GSW by the bundle at wholesale pricing.', '[{"q":"Schedule 40 or Schedule 80 — which do I need?","a":"Schedule 40 is standard for underground and encased work; Schedule 80 is for exposed locations where physical protection is required, and for stub-ups. Drawings typically call it out — we stock both."},{"q":"Do you stock the fittings to match?","a":"Yes — couplings, elbows (including factory 90s), adapters, expansion fittings and solvent cement are all on the shelf, so the underground package comes from one order."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('emt-conduit-1in-10ft', 'GSW-EMTCONDUIT', 'EMT Conduit 1" x 10ft', 'electrical-materials', 'emt-conduit-fittings', 14.2, 17, false, 'Electro-galvanized EMT raceway for exposed and concealed commercial runs.', 'Electro-galvanized EMT raceway for exposed and concealed commercial runs.', '["1\" trade size, 10 ft length","Hot-dip galvanized steel","cULus listed | CSA certified","Bundle pricing available"]'::jsonb, 'in-stock', 'EMT Conduit 1" x 10ft Canada', 'Buy the EMT Conduit 1" x 10ft wholesale in Canada. 1" trade size, 10 ft length — cULus/DLC certified, flat $30 shipping.', 'The EMT Conduit 1" x 10ft is cULus-listed EMT raceway or a matching steel fitting for exposed and concealed commercial work. 1" trade size, 10 ft length — straight, burr-free conduit that pulls clean, with compression and set-screw connectors that tighten without stripping. Commercial contractors across the GTA order EMT from GSW by the bundle with next-day counter availability.', '[{"q":"Compression or set-screw connectors?","a":"Compression connectors are the default for most commercial work — they seal better and pull better. Set-screw types are acceptable indoors in dry locations where the spec allows. We stock both in every trade size."},{"q":"Do you sell EMT by the bundle?","a":"Yes — 10-foot lengths come bundled, and bundle pricing beats per-stick pricing significantly. Mixed-size orders are no problem; call for your contractor tier."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('emt-connector-compression-1in', 'GSW-EMTCONNECT', 'EMT Compression Connector 1"', 'electrical-materials', 'emt-conduit-fittings', 1.9, 2.5, false, 'Steel compression-type EMT connector with insulated throat for fast, secure pulls.', 'Steel compression-type EMT connector with insulated throat for fast, secure pulls.', '["1\" trade size, compression type","Zinc-plated steel, insulated throat","cULus listed | CSA certified","Qty pricing per 100-pack"]'::jsonb, 'in-stock', 'EMT Compression Connector 1" Canada', 'Buy the EMT Compression Connector 1" wholesale in Canada. 1" trade size, compression type — cULus/DLC certified, flat $30 shipping.', 'The EMT Compression Connector 1" is cULus-listed EMT raceway or a matching steel fitting for exposed and concealed commercial work. 1" trade size, compression type — straight, burr-free conduit that pulls clean, with compression and set-screw connectors that tighten without stripping. Commercial contractors across the GTA order EMT from GSW by the bundle with next-day counter availability.', '[{"q":"Compression or set-screw connectors?","a":"Compression connectors are the default for most commercial work — they seal better and pull better. Set-screw types are acceptable indoors in dry locations where the spec allows. We stock both in every trade size."},{"q":"Do you sell EMT by the bundle?","a":"Yes — 10-foot lengths come bundled, and bundle pricing beats per-stick pricing significantly. Mixed-size orders are no problem; call for your contractor tier."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('floor-heating-cable-40sqft', 'GSW-FLOORHEATI', 'Floor Heating Cable Kit – 40 sq ft', 'electrical-materials', 'floor-heating-cable-thermostat', 210, 260, false, 'Electric in-floor heating cable kit covering ~40 sq ft of tile or stone floor.', 'Electric in-floor heating cable kit covering ~40 sq ft of tile or stone floor.', '["Covers approx. 40 sq ft","120V, 3.7 W/ft","cULus listed | GFCI protected","Includes strapping & manual"]'::jsonb, 'in-stock', 'Floor Heating Cable Kit – 40 sq ft', 'Buy the Floor Heating Cable Kit – 40 sq ft wholesale in Canada. Covers approx. 40 sq ft — cULus/DLC certified, flat $30 shipping.', 'The Floor Heating Cable Kit – 40 sq ft is a cULus-listed electric floor heating component for warm tile, stone and laminate floors. Covers approx. 40 sq ft with GFCI protection built in and thermostats that hold the floor exactly where the homeowner wants it. Renovation contractors across the GTA buy floor heating from GSW because we stock kits and matching thermostats together with technical backup on layout.', '[{"q":"How much cable do I need for my floor?","a":"Cable kits are sized by area — measure the open floor minus fixed objects (tub, vanity, toilet) and choose the kit that covers it. Never cut or overlap heating cable; if the area is between kit sizes, choose the smaller and adjust spacing. We will walk you through it by phone."},{"q":"Does floor heating need a dedicated circuit?","a":"Larger kits do — sizing depends on total wattage. The thermostat and cable ratings are on the spec; send us the layout and load and we will confirm the circuit requirements."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('programmable-floor-thermostat', 'GSW-PROGRAMMAB', 'Programmable Floor Heating Thermostat', 'electrical-materials', 'floor-heating-cable-thermostat', 68, null, false, 'Touch-screen programmable thermostat with floor sensor for heating cable systems.', 'Touch-screen programmable thermostat with floor sensor for heating cable systems.', '["120/240V, 15A switching","7-day programmable, floor/air sensor","cULus listed | CSA certified","Works with GSW cable kits"]'::jsonb, 'in-stock', 'Programmable Floor Heating Thermos…', 'Buy the Programmable Floor Heating Thermostat wholesale in Canada. 120/240V, 15A switching — cULus/DLC certified, flat $30 shipping.', 'The Programmable Floor Heating Thermostat is a cULus-listed electric floor heating component for warm tile, stone and laminate floors. 120/240V, 15A switching with GFCI protection built in and thermostats that hold the floor exactly where the homeowner wants it. Renovation contractors across the GTA buy floor heating from GSW because we stock kits and matching thermostats together with technical backup on layout.', '[{"q":"How much cable do I need for my floor?","a":"Cable kits are sized by area — measure the open floor minus fixed objects (tub, vanity, toilet) and choose the kit that covers it. Never cut or overlap heating cable; if the area is between kit sizes, choose the smaller and adjust spacing. We will walk you through it by phone."},{"q":"Does floor heating need a dedicated circuit?","a":"Larger kits do — sizing depends on total wattage. The thermostat and cable ratings are on the spec; send us the layout and load and we will confirm the circuit requirements."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('bath-fan-80cfm-quiet', 'GSW-BATHFAN80C', 'Bathroom Exhaust Fan 80 CFM – Quiet', 'electrical-materials', 'bathroom-exhaust-fan', 58, 72, false, '0.8-sones quiet bathroom fan for mid-size bathrooms, energy-star rated.', '0.8-sones quiet bathroom fan for mid-size bathrooms, energy-star rated.', '["80 CFM | 0.8 sones","ENERGY STAR qualified","cULus listed | CSA certified","Ceiling mount, 4\" duct"]'::jsonb, 'in-stock', 'Bathroom Exhaust Fan 80 CFM – Quiet', 'Buy the Bathroom Exhaust Fan 80 CFM – Quiet wholesale in Canada. 80 CFM | 0.8 sones — cULus/DLC certified, flat $30 shipping.', 'The Bathroom Exhaust Fan 80 CFM – Quiet is an ENERGY STAR-rated bathroom exhaust fan that clears moisture quietly and reliably. 80 CFM | 0.8 sones — sized for real bathrooms with the duct connections and grilles contractors prefer. Builders and renovators across Mississauga and Toronto buy exhaust fans from GSW at wholesale pricing with volume stock for multi-bathroom jobs.', '[{"q":"What CFM do I need for my bathroom?","a":"Rule of thumb: 1 CFM per square foot of bathroom, minimum 50 CFM, and add capacity for high ceilings or jetted tubs. An 80 CFM fan covers most standard bathrooms; large ensuites may want 110 CFM."},{"q":"What does \"sones\" mean?","a":"Sones measure perceived loudness — lower is quieter. Under 1.0 sone is nearly inaudible; 3+ sones is clearly noticeable. We stock quiet models because homeowners complain about noise more than any other fan spec."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('bath-fan-humidity-110cfm', 'GSW-BATHFANHUM', 'Bathroom Fan 110 CFM with Humidity Sensor', 'electrical-materials', 'bathroom-exhaust-fan', 88, null, false, 'High-capacity humidity-sensing exhaust fan that runs automatically when moisture rises.', 'High-capacity humidity-sensing exhaust fan that runs automatically when moisture rises.', '["110 CFM | 1.2 sones","Built-in humidity sensor","ENERGY STAR | cULus listed","6\" duct, motion-sensor option"]'::jsonb, 'in-stock', 'Bathroom Fan 110 CFM with Humidity…', 'Buy the Bathroom Fan 110 CFM with Humidity Sensor wholesale in Canada. 110 CFM | 1.2 sones — cULus/DLC certified, flat $30 shipping.', 'The Bathroom Fan 110 CFM with Humidity Sensor is an ENERGY STAR-rated bathroom exhaust fan that clears moisture quietly and reliably. 110 CFM | 1.2 sones — sized for real bathrooms with the duct connections and grilles contractors prefer. Builders and renovators across Mississauga and Toronto buy exhaust fans from GSW at wholesale pricing with volume stock for multi-bathroom jobs.', '[{"q":"What CFM do I need for my bathroom?","a":"Rule of thumb: 1 CFM per square foot of bathroom, minimum 50 CFM, and add capacity for high ceilings or jetted tubs. An 80 CFM fan covers most standard bathrooms; large ensuites may want 110 CFM."},{"q":"What does \"sones\" mean?","a":"Sones measure perceived loudness — lower is quieter. Under 1.0 sone is nearly inaudible; 3+ sones is clearly noticeable. We stock quiet models because homeowners complain about noise more than any other fan spec."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('vapor-barrier-6mil-8x100', 'GSW-VAPORBARRI', 'Vapor Barrier 6-mil – 8ft x 100ft', 'electrical-materials', 'vapor-barrier', 42, 52, false, '6-mil polyethylene vapor barrier for interior foundation walls and crawl spaces.', '6-mil polyethylene vapor barrier for interior foundation walls and crawl spaces.', '["6 mil thickness","8 ft x 100 ft roll (800 sq ft)","ASTM E1745 Class A compliant","Puncture & tear resistant"]'::jsonb, 'in-stock', 'Vapor Barrier 6-mil – 8ft x 100ft', 'Buy the Vapor Barrier 6-mil – 8ft x 100ft wholesale in Canada. 6 mil thickness — cULus/DLC certified, flat $30 shipping.', 'The Vapor Barrier 6-mil – 8ft x 100ft is code-compliant polyethylene sheeting for interior foundation walls, crawl spaces and slab undersides — the moisture control layer Ontario building code expects. 6 mil thickness. Foundation and renovation contractors across the GTA pick up vapor barrier from GSW along with their electrical order, one stop, one flat-rate delivery.', '[{"q":"How thick should a vapor barrier be?","a":"Ontario code references 6-mil (0.15 mm) polyethylene minimum for residential applications, with taped seams. We stock 6-mil rolls and the tuck tape to seal them."},{"q":"Vapor barrier or vapour-permeable membrane?","a":"They solve opposite problems — vapor barriers stop interior moisture reaching cold surfaces; breathable membranes let assemblies dry. For interior basement walls in Ontario, 6-mil poly on the warm side is the standard. Call us if the drawing specifies otherwise."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('vapor-barrier-tuck-tape', 'GSW-VAPORBARRI', 'Vapor Barrier Tuck Tape 60mm x 55m', 'electrical-materials', 'vapor-barrier', 8.5, null, false, 'Red sheathing tape for sealing vapor barrier overlaps and penetrations.', 'Red sheathing tape for sealing vapor barrier overlaps and penetrations.', '["60 mm x 55 m roll","Aggressive acrylic adhesive","-18°C to +82°C rated","Case of 24 available"]'::jsonb, 'in-stock', 'Vapor Barrier Tuck Tape 60mm x 55m', 'Buy the Vapor Barrier Tuck Tape 60mm x 55m wholesale in Canada. 60 mm x 55 m roll — cULus/DLC certified, flat $30 shipping.', 'The Vapor Barrier Tuck Tape 60mm x 55m is code-compliant polyethylene sheeting for interior foundation walls, crawl spaces and slab undersides — the moisture control layer Ontario building code expects. 60 mm x 55 m roll. Foundation and renovation contractors across the GTA pick up vapor barrier from GSW along with their electrical order, one stop, one flat-rate delivery.', '[{"q":"How thick should a vapor barrier be?","a":"Ontario code references 6-mil (0.15 mm) polyethylene minimum for residential applications, with taped seams. We stock 6-mil rolls and the tuck tape to seal them."},{"q":"Vapor barrier or vapour-permeable membrane?","a":"They solve opposite problems — vapor barriers stop interior moisture reaching cold surfaces; breathable membranes let assemblies dry. For interior basement walls in Ontario, 6-mil poly on the warm side is the standard. Call us if the drawing specifies otherwise."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('smoke-alarm-hardwired-interconnected', 'GSW-SMOKEALARM', 'Hardwired Interconnected Smoke Alarm', 'electrical-materials', 'emergency-smoke-alarm', 32, 39, false, '120V hardwired photoelectric smoke alarm with 9V battery backup and interconnect.', '120V hardwired photoelectric smoke alarm with 9V battery backup and interconnect.', '["Photoelectric sensing chamber","120V hardwired + battery backup","Interconnect up to 18 devices","cULus listed | CSA 6.76 compliant"]'::jsonb, 'in-stock', 'Hardwired Interconnected Smoke Ala…', 'Buy the Hardwired Interconnected Smoke Alarm wholesale in Canada. Photoelectric sensing chamber — cULus/DLC certified, flat $30 shipping.', 'The Hardwired Interconnected Smoke Alarm is a cULus-listed hardwired smoke or combination alarm for code-compliant residential protection. Photoelectric sensing chamber with battery backup so protection continues through outages. Electrical contractors and builders across the GTA buy smoke alarms from GSW in case quantities, matched to Ontario Fire Code and OBC requirements.', '[{"q":"How many smoke alarms does my project need?","a":"Ontario Fire Code requires one on every storey and outside sleeping areas, plus one in every bedroom for new construction — interconnected so one alarm sounds them all. Send us the floor plans and we will count the exact requirement."},{"q":"Photoelectric or ionization?","a":"Photoelectric sensors detect smouldering fires faster with fewer nuisance trips from cooking — which is why modern code and most contractors prefer them. Combination CO units add carbon monoxide protection where fuel-burning appliances exist."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('smoke-co-combo-alarm', 'GSW-SMOKECOCOM', 'Smoke & CO Combo Alarm – Hardwired', 'electrical-materials', 'emergency-smoke-alarm', 48, 58, false, 'Combination smoke and carbon monoxide alarm with voice alerts and battery backup.', 'Combination smoke and carbon monoxide alarm with voice alerts and battery backup.', '["Smoke + electrochemical CO sensor","Voice warning & location feature","120V hardwired, interconnectable","cULus | CSA 6.76 / 6.19"]'::jsonb, 'in-stock', 'Smoke & CO Combo Alarm – Hardwired', 'Buy the Smoke & CO Combo Alarm – Hardwired wholesale in Canada. Smoke + electrochemical CO sensor — cULus/DLC certified, flat $30 shipping.', 'The Smoke & CO Combo Alarm – Hardwired is a cULus-listed hardwired smoke or combination alarm for code-compliant residential protection. Smoke + electrochemical CO sensor with battery backup so protection continues through outages. Electrical contractors and builders across the GTA buy smoke alarms from GSW in case quantities, matched to Ontario Fire Code and OBC requirements.', '[{"q":"How many smoke alarms does my project need?","a":"Ontario Fire Code requires one on every storey and outside sleeping areas, plus one in every bedroom for new construction — interconnected so one alarm sounds them all. Send us the floor plans and we will count the exact requirement."},{"q":"Photoelectric or ionization?","a":"Photoelectric sensors detect smouldering fires faster with fewer nuisance trips from cooking — which is why modern code and most contractors prefer them. Combination CO units add carbon monoxide protection where fuel-burning appliances exist."}]'::jsonb, null);
