insert into public.homepage_sections (section_key, title, subtitle, body, is_active, sort_order) values ('about_teaser', 'About Teaser', 'Short paragraph above the footer CTA on the homepage', '{"text": "GSW is an electrical and lighting distributor and wholesaler, offering a full line of high quality products along with dependable technical expertise and personalized customer service."}', true, 2);
